        "birth.name": ["en": "Name, if you want it on the chart", "zh-Hans": "姓名（如需显示于命盘）", "zh-Hant": "姓名（如需顯示於命盤）", "ja": "名前（命式に載せる場合）", "ko": "이름 (명식에 표시할 경우)", "vi": "Tên, nếu muốn hiện trên lá số", "es": "Nombre, si lo quieres en la carta", "fr": "Nom, si vous le voulez sur le thème", "de": "Name, falls er im Horoskop stehen soll", "ru": "Имя, если нужно в карте", "ar": "الاسم، إن أردته على المخطط"],
        "birth.place": ["en": "Place", "zh-Hans": "地点", "zh-Hant": "地點", "ja": "場所", "ko": "장소", "vi": "Nơi sinh", "es": "Lugar", "fr": "Lieu", "de": "Ort", "ru": "Место", "ar": "المكان"],
        "birth.solarNote": ["en": "Longitude and the offset give true solar time, which is what the hour pillar is taken from.", "zh-Hans": "经度与时差用以求真太阳时，时柱即由此定。", "zh-Hant": "經度與時差用以求真太陽時，時柱即由此定。", "ja": "経度と時差から真太陽時を求め、そこから時柱を立てます。", "ko": "경도와 시차로 진태양시를 구하고, 거기서 시주를 세웁니다.", "vi": "Kinh độ và độ lệch cho giờ mặt trời thật, tức là căn cứ của trụ giờ.", "es": "La longitud y el desfase dan la hora solar verdadera, de la que se toma el pilar horario.", "fr": "La longitude et le décalage donnent l'heure solaire vraie, dont on tire le pilier horaire.", "de": "Längengrad und Zeitversatz ergeben die wahre Sonnenzeit, aus der die Stundensäule stammt.", "ru": "Долгота и смещение дают истинное солнечное время, из которого берётся часовой столп.", "ar": "يعطي خط الطول والفارق الزمني الوقت الشمسي الحقيقي، ومنه يُؤخذ عمود الساعة."],
        "birth.timeKnown": ["en": "I know the hour", "zh-Hans": "知道时辰", "zh-Hant": "知道時辰", "ja": "時刻がわかる", "ko": "시각을 압니다", "vi": "Tôi biết giờ sinh", "es": "Sé la hora", "fr": "Je connais l'heure", "de": "Ich kenne die Stunde", "ru": "Я знаю час", "ar": "أعرف الساعة"],
        "birth.timeUnknown": ["en": "time unknown", "zh-Hans": "时辰不详", "zh-Hant": "時辰不詳", "ja": "時刻不明", "ko": "시각 모름", "vi": "không rõ giờ", "es": "hora desconocida", "fr": "heure inconnue", "de": "Stunde unbekannt", "ru": "час неизвестен", "ar": "الساعة غير معروفة"],
        "birth.utcOffset": ["en": "Hours from UTC", "zh-Hans": "与 UTC 时差", "zh-Hant": "與 UTC 時差", "ja": "UTCとの時差", "ko": "UTC와의 시차", "vi": "Lệch giờ so với UTC", "es": "Horas desde UTC", "fr": "Décalage UTC", "de": "Stunden zu UTC", "ru": "Смещение от UTC", "ar": "الفارق عن UTC"],
        "blurb.almanac": ["en": "What today suits, and what it does not", "zh-Hans": "今日宜什么，忌什么", "zh-Hant": "今日宜什麼，忌什麼", "ja": "今日に向くこと、向かないこと", "ko": "오늘 마땅한 일과 꺼리는 일", "vi": "Hôm nay nên gì, kiêng gì", "es": "Qué conviene hoy y qué no", "fr": "Ce qui convient aujourd'hui, et ce qui non", "de": "Was der Tag trägt und was nicht", "ru": "Что подходит сегодня, а что нет", "ar": "ما يناسب اليوم وما لا يناسبه"],
        "blurb.answers": ["en": "Ask once. The page falls where it falls", "zh-Hans": "问一次，书页自会落定", "zh-Hant": "問一次，書頁自會落定", "ja": "一度だけ問う。頁は落ちるところに落ちる", "ko": "한 번만 묻습니다. 책장은 떨어질 곳에 떨어집니다", "vi": "Hỏi một lần. Trang sách rơi vào đâu là ở đó", "es": "Pregunta una vez. La página cae donde cae", "fr": "Demandez une fois. La page tombe où elle tombe", "de": "Frage einmal. Die Seite fällt, wohin sie fällt", "ru": "Спросите один раз. Страница ляжет как ляжет", "ar": "اسأل مرة واحدة. تقع الصفحة حيث تقع"],
        "blurb.astrology": ["en": "The sky at your birth, and where it stands now", "zh-Hans": "出生时的天象，与此刻的行运", "zh-Hant": "出生時的天象，與此刻的行運", "ja": "誕生時の空と、いまの運行", "ko": "태어난 때의 하늘과 지금의 운행", "vi": "Bầu trời lúc bạn sinh, và hiện tại", "es": "El cielo de tu nacimiento y dónde está ahora", "fr": "Le ciel de votre naissance, et où il en est", "de": "Der Himmel Ihrer Geburt, und wo er heute steht", "ru": "Небо при вашем рождении и его нынешнее положение", "ar": "سماء ميلادك، وأين هي الآن"],
        "blurb.bazi": ["en": "Four pillars, from the hour you were born", "zh-Hans": "四柱，取自你出生的时辰", "zh-Hant": "四柱，取自你出生的時辰", "ja": "生まれた時刻から立てる四柱", "ko": "태어난 시각에서 세우는 사주", "vi": "Tứ trụ, lấy từ giờ sinh của bạn", "es": "Cuatro pilares, desde tu hora de nacimiento", "fr": "Quatre piliers, à partir de votre heure de naissance", "de": "Vier Säulen, aus Ihrer Geburtsstunde", "ru": "Четыре столпа — от часа вашего рождения", "ar": "أربعة أعمدة، من ساعة ميلادك"],
        "blurb.face": ["en": "Three courts, five eyes, twelve palaces", "zh-Hans": "三停、五眼、十二宫", "zh-Hant": "三停、五眼、十二宮", "ja": "三停・五眼・十二宮", "ko": "삼정·오안·십이궁", "vi": "Tam đình, ngũ nhãn, thập nhị cung", "es": "Tres cortes, cinco ojos, doce palacios", "fr": "Trois cours, cinq yeux, douze palais", "de": "Drei Höfe, fünf Augen, zwölf Paläste", "ru": "Три части, пять глаз, двенадцать дворцов", "ar": "ثلاثة أقسام، خمس أعين، اثنا عشر قصراً"],
        "blurb.fengshui": ["en": "Your eight mansions, and the sector you face", "zh-Hans": "你的八宅，与此刻所朝之方", "zh-Hant": "你的八宅，與此刻所朝之方", "ja": "あなたの八宅と、いま向いている方位", "ko": "당신의 팔택과 지금 향한 방위", "vi": "Bát trạch của bạn, và hướng đang quay mặt", "es": "Tus ocho mansiones y el sector que miras", "fr": "Vos huit demeures, et le secteur que vous regardez", "de": "Ihre acht Häuser, und der Sektor, dem Sie zugewandt sind", "ru": "Ваши восемь дворцов и сектор, куда вы обращены", "ar": "منازلك الثمانية، والقطاع الذي تواجهه"],
        "blurb.iching": ["en": "Coins or yarrow, and the lines that change", "zh-Hans": "铜钱或蓍草，以及变爻", "zh-Hant": "銅錢或蓍草，以及變爻", "ja": "銅銭か筮竹、そして変爻", "ko": "동전이나 시초, 그리고 변효", "vi": "Đồng tiền hay cỏ thi, và hào động", "es": "Monedas o milenrama, y las líneas que cambian", "fr": "Pièces ou achillée, et les lignes qui changent", "de": "Münzen oder Schafgarbe, und die wandelnden Linien", "ru": "Монеты или тысячелистник и меняющиеся черты", "ar": "عملات أو يارو، والخطوط المتغيّرة"],
        "blurb.palm": ["en": "The hand, measured rather than guessed", "zh-Hans": "手相以量度而非揣测", "zh-Hant": "手相以量度而非揣測", "ja": "手は推測ではなく計測で読む", "ko": "손은 짐작이 아니라 측정으로", "vi": "Bàn tay được đo, không phải đoán", "es": "La mano, medida en vez de adivinada", "fr": "La main, mesurée plutôt que devinée", "de": "Die Hand, gemessen statt geraten", "ru": "Ладонь измеряют, а не угадывают", "ar": "اليد تُقاس لا تُخمَّن"],
        "blurb.tarot": ["en": "One card, three, or the Celtic cross", "zh-Hans": "一张、三张，或凯尔特十字", "zh-Hant": "一張、三張，或凱爾特十字", "ja": "一枚、三枚、あるいはケルト十字", "ko": "한 장, 세 장, 혹은 켈트 십자", "vi": "Một lá, ba lá, hoặc thập tự Celtic", "es": "Una carta, tres o la cruz celta", "fr": "Une carte, trois, ou la croix celtique", "de": "Eine Karte, drei, oder das keltische Kreuz", "ru": "Одна карта, три или кельтский крест", "ar": "بطاقة واحدة أو ثلاث أو الصليب السلتي"],
        "camera.back": ["en": "Back", "zh-Hans": "后置", "zh-Hant": "後鏡頭", "ja": "背面", "ko": "후면", "vi": "Sau", "es": "Trasera", "fr": "Arrière", "de": "Hinten", "ru": "Основная", "ar": "خلفية"],
        "camera.denied": ["en": "Camera access is disabled. Allow it in Settings to use this feature.", "zh-Hans": "相机访问已禁用。请在设置中允许以使用此功能。", "zh-Hant": "相機存取已停用。請在設定中允許以使用此功能。", "ja": "カメラへのアクセスが無効です。この機能を使用するには設定で許可してください。", "ko": "카메라 접근이 비활성화되어 있습니다. 이 기능을 사용하려면 설정에서 허용해 주세요.", "vi": "Quyền truy cập camera đã bị tắt. Hãy cho phép trong Cài đặt để sử dụng tính năng này.", "es": "El acceso a la cámara está desactivado. Permítelo en Ajustes para usar esta función.", "fr": "L'accès à la caméra est désactivé. Autorisez-le dans les Réglages pour utiliser cette fonction.", "de": "Der Kamerazugriff ist deaktiviert. Erlaube ihn in den Einstellungen, um diese Funktion zu nutzen.", "ru": "Доступ к камере отключён. Разрешите его в настройках, чтобы использовать эту функцию.", "ar": "تم تعطيل الوصول إلى الكاميرا. اسمح به في الإعدادات لاستخدام هذه الميزة."],
        "camera.front": ["en": "Front", "zh-Hans": "前置", "zh-Hant": "前鏡頭", "ja": "前面", "ko": "전면", "vi": "Trước", "es": "Frontal", "fr": "Avant", "de": "Vorn", "ru": "Фронтальная", "ar": "أمامية"],
        "camera.needed": ["en": "Auspice needs the camera for this reading.", "zh-Hans": "此项解读需要使用相机。", "zh-Hant": "此項解讀需要使用相機。", "ja": "この鑑定にはカメラが必要です。", "ko": "이 해석에는 카메라가 필요합니다.", "vi": "Phần luận này cần dùng máy ảnh.", "es": "Auspice necesita la cámara para esta lectura.", "fr": "Auspice a besoin de la caméra pour cette lecture.", "de": "Auspice benötigt für diese Deutung die Kamera.", "ru": "Для этого чтения нужна камера.", "ar": "يحتاج أوسبيس إلى الكاميرا لهذه القراءة."],
        "camera.retry": ["en": "The camera could not start. Please try again.", "zh-Hans": "相机无法启动。请重试。", "zh-Hant": "相機無法啟動。請重試。", "ja": "カメラを起動できませんでした。もう一度お試しください。", "ko": "카메라를 시작할 수 없습니다. 다시 시도해 주세요.", "vi": "Không thể khởi động camera. Vui lòng thử lại.", "es": "No se pudo iniciar la cámara. Inténtalo de nuevo.", "fr": "La caméra n'a pas pu démarrer. Veuillez réessayer.", "de": "Die Kamera konnte nicht gestartet werden. Bitte versuche es erneut.", "ru": "Не удалось запустить камеру. Пожалуйста, попробуйте снова.", "ar": "تعذر تشغيل الكاميرا. يرجى المحاولة مرة أخرى."],
        "camera.unavailable": ["en": "No camera is available on this device.", "zh-Hans": "此设备上没有可用的相机。", "zh-Hant": "此裝置上沒有可用的相機。", "ja": "このデバイスには利用可能なカメラがありません。", "ko": "이 기기에는 사용 가능한 카메라가 없습니다.", "vi": "Không có camera khả dụng trên thiết bị này.", "es": "No hay ninguna cámara disponible en este dispositivo.", "fr": "Aucune caméra n'est disponible sur cet appareil.", "de": "Auf diesem Gerät ist keine Kamera verfügbar.", "ru": "На этом устройстве нет доступной камеры.", "ar": "لا توجد كاميرا متاحة على هذا الجهاز."],
        "chat.allConversations": ["en": "Conversations", "zh-Hans": "历史对话", "zh-Hant": "歷史對話", "ja": "対話の履歴", "ko": "대화 기록", "vi": "Các cuộc trò chuyện", "es": "Conversaciones", "fr": "Conversations", "de": "Gespräche", "ru": "Беседы", "ar": "المحادثات"],
        "chat.ask": ["en": "Ask…", "zh-Hans": "请问……", "zh-Hant": "請問……", "ja": "たずねる…", "ko": "물어보기…", "vi": "Hỏi…", "es": "Pregunta…", "fr": "Demandez…", "de": "Fragen …", "ru": "Спросите…", "ar": "اسأل…"],
        "chat.connectionFailed": ["en": "The response was interrupted. Check your connection and retry.", "zh-Hans": "回答中断了，请检查网络后重试。", "zh-Hant": "回答中斷了，請檢查網路後重試。", "ja": "回答が中断されました。接続を確認して再試行してください。", "ko": "응답이 중단되었습니다. 연결을 확인하고 다시 시도해 주세요.", "vi": "Phản hồi bị gián đoạn. Kiểm tra kết nối và thử lại.", "es": "La respuesta se interrumpió. Comprueba la conexión y reintenta.", "fr": "La réponse a été interrompue. Vérifiez la connexion et réessayez.", "de": "Die Antwort wurde unterbrochen. Verbindung prüfen und erneut versuchen.", "ru": "Ответ прерван. Проверьте соединение и повторите попытку.", "ar": "انقطع الرد. تحقق من الاتصال وأعد المحاولة."],
        "chat.earlier": ["en": "earlier messages, kept and summarised", "zh-Hans": "条较早的消息，已保存并摘要", "zh-Hant": "則較早的訊息，已保存並摘要", "ja": "件の以前のメッセージ（保存・要約済み）", "ko": "개의 이전 메시지, 저장되고 요약됨", "vi": "tin nhắn trước đó, đã lưu và tóm tắt", "es": "mensajes anteriores, guardados y resumidos", "fr": "messages plus anciens, conservés et résumés", "de": "frühere Nachrichten, gespeichert und zusammengefasst", "ru": "более ранних сообщений, сохранены и сжаты", "ar": "رسائل سابقة، محفوظة وملخّصة"],
        "chat.latest": ["en": "Latest messages", "zh-Hans": "回到底部", "zh-Hant": "回到底部", "ja": "最新のメッセージ", "ko": "최신 메시지", "vi": "Tin nhắn mới nhất", "es": "Últimos mensajes", "fr": "Derniers messages", "de": "Neueste Nachrichten", "ru": "Последние сообщения", "ar": "أحدث الرسائل"],
        "chat.messages": ["en": "messages", "zh-Hans": "条消息", "zh-Hant": "則訊息", "ja": "件", "ko": "개", "vi": "tin nhắn", "es": "mensajes", "fr": "messages", "de": "Nachrichten", "ru": "сообщений", "ar": "رسائل"],
        "chat.newConversation": ["en": "New conversation", "zh-Hans": "新建对话", "zh-Hant": "新建對話", "ja": "新しい対話", "ko": "새 대화", "vi": "Cuộc trò chuyện mới", "es": "Nueva conversación", "fr": "Nouvelle conversation", "de": "Neues Gespräch", "ru": "Новая беседа", "ar": "محادثة جديدة"],
        "chat.opener": ["en": "Ask about today, or about a chart.", "zh-Hans": "可问今日，也可问命盘。", "zh-Hant": "可問今日，也可問命盤。", "ja": "今日のことでも、命式のことでも。", "ko": "오늘에 대해서도, 명식에 대해서도 물어보세요.", "vi": "Hỏi về hôm nay, hoặc về lá số.", "es": "Pregunta por hoy, o por una carta astral.", "fr": "Posez une question sur aujourd'hui, ou sur un thème.", "de": "Fragen Sie nach heute oder nach einem Horoskop.", "ru": "Спросите о сегодняшнем дне или о карте.", "ar": "اسأل عن اليوم، أو عن مخطط."],
        "chat.quiet": ["en": "The reading service went quiet. Ask again and it will pick up where it left off.", "zh-Hans": "解读服务未有回应。再问一次即可接着上文。", "zh-Hant": "解讀服務未有回應。再問一次即可接著上文。", "ja": "鑑定サービスが応答しませんでした。もう一度たずねれば、続きから再開します。", "ko": "해석 서비스가 응답하지 않았습니다. 다시 물으면 이어서 계속합니다.", "vi": "Dịch vụ luận giải im lặng. Hỏi lại và nó sẽ tiếp tục từ chỗ dừng.", "es": "El servicio de lectura se quedó en silencio. Pregunta otra vez y continuará donde lo dejó.", "fr": "Le service de lecture est resté muet. Redemandez et il reprendra où il s'est arrêté.", "de": "Der Deutungsdienst blieb stumm. Fragen Sie erneut, er setzt fort, wo er aufgehört hat.", "ru": "Служба толкования промолчала. Спросите снова — она продолжит с того же места.", "ar": "صمتت خدمة القراءة. اسأل مرة أخرى وستكمل من حيث توقفت."],
        "chat.reading": ["en": "reading…", "zh-Hans": "解读中……", "zh-Hant": "解讀中……", "ja": "読み解き中…", "ko": "해석 중…", "vi": "đang luận…", "es": "leyendo…", "fr": "lecture…", "de": "deutet …", "ru": "читаю…", "ar": "يقرأ…"],
        "chat.retry": ["en": "Retry answer", "zh-Hans": "重试回答", "zh-Hant": "重試回答", "ja": "回答を再試行", "ko": "답변 재시도", "vi": "Thử trả lời lại", "es": "Reintentar respuesta", "fr": "Réessayer", "de": "Antwort erneut versuchen", "ru": "Повторить ответ", "ar": "إعادة المحاولة"],
        "chat.stop": ["en": "Stop", "zh-Hans": "停止", "zh-Hant": "停止", "ja": "停止", "ko": "중지", "vi": "Dừng", "es": "Detener", "fr": "Arrêter", "de": "Stoppen", "ru": "Остановить", "ar": "إيقاف"],
        "chat.stopped": ["en": "Response stopped. You can retry.", "zh-Hans": "已停止回答，可以重试。", "zh-Hant": "已停止回答，可以重試。", "ja": "回答を停止しました。再試行できます。", "ko": "응답을 중지했습니다. 다시 시도할 수 있습니다.", "vi": "Đã dừng trả lời. Bạn có thể thử lại.", "es": "Respuesta detenida. Puedes reintentar.", "fr": "Réponse arrêtée. Vous pouvez réessayer.", "de": "Antwort gestoppt. Du kannst es erneut versuchen.", "ru": "Ответ остановлен. Можно повторить.", "ar": "تم إيقاف الرد. يمكنك إعادة المحاولة."],
        "chat.timeout": ["en": "The response took too long. Please retry.", "zh-Hans": "回答等待超时，请重试。", "zh-Hant": "回答等待逾時，請重試。", "ja": "回答がタイムアウトしました。再試行してください。", "ko": "응답 시간이 초과되었습니다. 다시 시도해 주세요.", "vi": "Phản hồi quá lâu. Vui lòng thử lại.", "es": "La respuesta tardó demasiado. Reinténtalo.", "fr": "La réponse a pris trop de temps. Réessayez.", "de": "Die Antwort hat zu lange gedauert. Bitte erneut versuchen.", "ru": "Время ожидания ответа истекло. Повторите попытку.", "ar": "استغرق الرد وقتًا طويلًا. أعد المحاولة."],
