        "practice.astrology": ["en": "Astrology", "zh-Hans": "星盘", "zh-Hant": "星盤", "ja": "占星", "ko": "점성", "vi": "Chiêm tinh", "es": "Astrología", "fr": "Astrologie", "de": "Astrologie", "ru": "Астрология", "ar": "التنجيم"],
