        "practice.face": ["en": "Face Reading", "zh-Hans": "面相", "zh-Hant": "面相", "ja": "人相", "ko": "관상", "vi": "Xem tướng mặt", "es": "Lectura del rostro", "fr": "Physiognomonie", "de": "Gesichtlesen", "ru": "Физиогномика", "ar": "قراءة الوجه"],
        "practice.fengshui": ["en": "Feng Shui", "zh-Hans": "风水", "zh-Hant": "風水", "ja": "風水", "ko": "풍수", "vi": "Phong thuỷ", "es": "Feng Shui", "fr": "Feng Shui", "de": "Feng Shui", "ru": "Фэн-шуй", "ar": "فنغ شوي"],
        "practice.iching": ["en": "I Ching", "zh-Hans": "易经", "zh-Hant": "易經", "ja": "易経", "ko": "주역", "vi": "Kinh Dịch", "es": "I Ching", "fr": "Yi Jing", "de": "I Ging", "ru": "И-цзин", "ar": "اليي تشينغ"],
        "practice.palm": ["en": "Palmistry", "zh-Hans": "手相", "zh-Hant": "手相", "ja": "手相", "ko": "수상", "vi": "Xem chỉ tay", "es": "Quiromancia", "fr": "Chiromancie", "de": "Handlesen", "ru": "Хиромантия", "ar": "قراءة الكف"],
        "practice.tarot": ["en": "Tarot", "zh-Hans": "塔罗", "zh-Hant": "塔羅", "ja": "タロット", "ko": "타로", "vi": "Tarot", "es": "Tarot", "fr": "Tarot", "de": "Tarot", "ru": "Таро", "ar": "التارو"],
        "settings.about": ["en": "About", "zh-Hans": "关于", "zh-Hant": "關於", "ja": "このアプリについて", "ko": "정보", "vi": "Giới thiệu", "es": "Acerca de", "fr": "À propos", "de": "Über", "ru": "О приложении", "ar": "حول"],
        "settings.language": ["en": "Language", "zh-Hans": "语言", "zh-Hant": "語言", "ja": "言語", "ko": "언어", "vi": "Ngôn ngữ", "es": "Idioma", "fr": "Langue", "de": "Sprache", "ru": "Язык", "ar": "اللغة"],
        "settings.languageSystem": ["en": "Match the phone", "zh-Hans": "跟随系统", "zh-Hant": "跟隨系統", "ja": "端末に合わせる", "ko": "기기 설정 따르기", "vi": "Theo hệ thống", "es": "Seguir al sistema", "fr": "Suivre le téléphone", "de": "Dem Gerät folgen", "ru": "Как на устройстве", "ar": "حسب الجهاز"],
        "settings.readings": ["en": "Readings", "zh-Hans": "解读", "zh-Hant": "解讀", "ja": "鑑定", "ko": "해석", "vi": "Luận giải", "es": "Lecturas", "fr": "Lectures", "de": "Deutungen", "ru": "Толкования", "ar": "القراءات"],
        "settings.readingsNote": ["en": "Charts, hexagrams, draws and the almanac are computed on this device and never leave it. When you ask for a reading in words, the question and the computed facts go to our own reading service, which holds the provider keys so this app does not have to.", "zh-Hans": "排盘、卦象、抽牌与黄历均在本机推算，不会外传。若你要求文字解读，则只将问题与已算得的事实送往我们自有的解读服务；密钥由该服务保管，应用本身不持有。", "zh-Hant": "排盤、卦象、抽牌與黃曆均在本機推算，不會外傳。若你要求文字解讀，則只將問題與已算得的事實送往我們自有的解讀服務；密鑰由該服務保管，應用本身不持有。", "ja": "命式・卦・カード・暦はすべて端末内で計算され、外に出ません。文章での鑑定を求めたときだけ、質問と計算済みの事実が自社の鑑定サービスへ送られます。鍵はそのサービスが持ち、アプリは持ちません。", "ko": "명식·괘·카드·역서는 모두 기기에서 계산되며 밖으로 나가지 않습니다. 문장 해석을 요청할 때만 질문과 계산된 사실이 자체 해석 서비스로 전달되며, 키는 그 서비스가 보관합니다.", "vi": "Lá số, quẻ, lá bài và lịch đều được tính trên máy và không rời thiết bị. Khi bạn yêu cầu luận giải bằng lời, câu hỏi và các dữ kiện đã tính được gửi tới dịch vụ luận giải của chúng tôi, nơi giữ khoá thay cho ứng dụng.", "es": "Las cartas, hexagramas, tiradas y el almanaque se calculan en este dispositivo y no salen de él. Cuando pides una lectura en palabras, la pregunta y los datos ya calculados van a nuestro propio servicio de lectura, que guarda las claves para que la app no tenga que hacerlo.", "fr": "Les thèmes, hexagrammes, tirages et l'almanach sont calculés sur cet appareil et n'en sortent pas. Lorsque vous demandez une lecture rédigée, la question et les faits déjà calculés vont à notre propre service, qui détient les clés à la place de l'application.", "de": "Horoskope, Hexagramme, Blätter und der Almanach werden auf diesem Gerät berechnet und verlassen es nicht. Wenn Sie eine ausformulierte Deutung wünschen, gehen Frage und bereits berechnete Fakten an unseren eigenen Deutungsdienst, der die Schlüssel hält, damit die App es nicht muss.", "ru": "Карты, гексаграммы, расклады и календарь вычисляются на устройстве и не покидают его. Когда вы просите толкование словами, вопрос и уже вычисленные факты уходят в нашу собственную службу, которая хранит ключи вместо приложения.", "ar": "تُحسب المخططات والسداسيات والسحبات والتقويم على هذا الجهاز ولا تغادره. وعندما تطلب قراءة مكتوبة، يذهب السؤال والحقائق المحسوبة إلى خدمة القراءة الخاصة بنا، وهي التي تحتفظ بالمفاتيح بدلاً من التطبيق."],
        "settings.rules": ["en": "Rules", "zh-Hans": "算法", "zh-Hant": "算法", "ja": "計算規則", "ko": "규칙", "vi": "Quy tắc", "es": "Reglas", "fr": "Règles", "de": "Regeln", "ru": "Правила", "ar": "القواعد"],
        "settings.rulesNote": ["en": "The same rules the web app runs, built from one source so they can never disagree.", "zh-Hans": "与网页版同源同规则，一处编写，不会彼此矛盾。", "zh-Hant": "與網頁版同源同規則，一處編寫，不會彼此矛盾。", "ja": "ウェブ版と同じ規則を同じソースから生成しているため、食い違いません。", "ko": "웹 버전과 같은 규칙을 한 소스에서 만들므로 서로 어긋날 수 없습니다.", "vi": "Cùng bộ quy tắc với bản web, dựng từ một nguồn nên không thể mâu thuẫn.", "es": "Las mismas reglas que ejecuta la versión web, construidas de una sola fuente para que nunca discrepen.", "fr": "Les mêmes règles que la version web, issues d'une seule source pour qu'elles ne puissent jamais diverger.", "de": "Dieselben Regeln wie in der Web-Version, aus einer Quelle erzeugt, damit sie nie auseinandergehen.", "ru": "Те же правила, что и в веб-версии, собранные из одного источника, чтобы они не расходились.", "ar": "القواعد نفسها التي تعمل بها نسخة الويب، مبنية من مصدر واحد فلا تتعارض أبداً."],
        "settings.version": ["en": "Version", "zh-Hans": "版本", "zh-Hant": "版本", "ja": "バージョン", "ko": "버전", "vi": "Phiên bản", "es": "Versión", "fr": "Version", "de": "Version", "ru": "Версия", "ar": "الإصدار"],
        "tarot.draw": ["en": "Shuffle and draw", "zh-Hans": "洗牌抽牌", "zh-Hant": "洗牌抽牌", "ja": "シャッフルして引く", "ko": "섞어서 뽑기", "vi": "Xáo và rút", "es": "Barajar y sacar", "fr": "Mélanger et tirer", "de": "Mischen und ziehen", "ru": "Перемешать и вытянуть", "ar": "اخلط واسحب"],
        "tarot.drawAgain": ["en": "Draw again", "zh-Hans": "再抽一次", "zh-Hant": "再抽一次", "ja": "もう一度引く", "ko": "다시 뽑기", "vi": "Rút lại", "es": "Sacar otra vez", "fr": "Tirer à nouveau", "de": "Noch einmal ziehen", "ru": "Вытянуть снова", "ar": "اسحب مرة أخرى"],
        "tarot.question": ["en": "Your question, if you have one", "zh-Hans": "若有所问，写于此处", "zh-Hant": "若有所問，寫於此處", "ja": "問いがあれば、ここに", "ko": "묻고 싶은 것이 있다면 적으세요", "vi": "Câu hỏi của bạn, nếu có", "es": "Tu pregunta, si la tienes", "fr": "Votre question, si vous en avez une", "de": "Ihre Frage, falls Sie eine haben", "ru": "Ваш вопрос, если он есть", "ar": "سؤالك، إن كان لديك"],
        "tarot.reversed": ["en": "REVERSED", "zh-Hans": "逆位", "zh-Hant": "逆位", "ja": "逆位置", "ko": "역방향", "vi": "NGƯỢC", "es": "INVERTIDA", "fr": "RENVERSÉE", "de": "UMGEKEHRT", "ru": "ПЕРЕВЁРНУТА", "ar": "معكوسة"],
        "tarot.tagline": ["en": "A full shuffle, seventy-eight cards, no card twice.", "zh-Hans": "全牌洗过，七十八张，绝不重复。", "zh-Hant": "全牌洗過，七十八張，絕不重複。", "ja": "七十八枚をすべて混ぜ、同じ札は二度出ません。", "ko": "일흔여덟 장을 모두 섞고, 같은 카드는 두 번 나오지 않습니다.", "vi": "Xáo trọn bộ bảy mươi tám lá, không lá nào lặp lại.", "es": "Una baraja completa, setenta y ocho cartas, ninguna repetida.", "fr": "Un mélange complet, soixante-dix-huit cartes, aucune deux fois.", "de": "Ein vollständiges Mischen, achtundsiebzig Karten, keine zweimal.", "ru": "Полная колода, семьдесят восемь карт, ни одной дважды.", "ar": "خلط كامل، ثمان وسبعون بطاقة، ولا بطاقة مرتين."],
        "tarot.tapToTurn": ["en": "Tap a card to turn it.", "zh-Hans": "点一张牌翻开。", "zh-Hant": "點一張牌翻開。", "ja": "カードをタップしてめくります。", "ko": "카드를 눌러 뒤집습니다.", "vi": "Chạm vào lá bài để lật.", "es": "Toca una carta para darle la vuelta.", "fr": "Touchez une carte pour la retourner.", "de": "Tippen Sie eine Karte an, um sie umzudrehen.", "ru": "Коснитесь карты, чтобы перевернуть.", "ar": "انقر بطاقة لقلبها."],
        "tarot.title": ["en": "Shuffle and draw", "zh-Hans": "洗牌抽牌", "zh-Hant": "洗牌抽牌", "ja": "シャッフルして引く", "ko": "섞고 뽑기", "vi": "Xáo và rút", "es": "Baraja y saca", "fr": "Mélangez et tirez", "de": "Mischen und ziehen", "ru": "Перемешать и вытянуть", "ar": "اخلط واسحب"],
        "vision.boundary": ["en": "Near a category boundary. Use the measured proportions rather than a single fixed label.", "zh-Hans": "接近分类边界，请以测得的比例为参考，不必固定归为一类。", "zh-Hant": "接近分類邊界，請以測得的比例為參考，不必固定歸為一類。", "ja": "分類の境界に近い結果です。一つの型に決めず、測定された比率を参考にしてください。", "ko": "분류 경계에 가까워요. 하나의 유형보다 측정된 비율을 참고하세요.", "vi": "Gần ranh giới phân loại. Hãy xem tỷ lệ đo được thay vì gán một nhãn cố định.", "es": "Está cerca de un límite entre categorías. Guíate por las proporciones medidas, no por una sola etiqueta.", "fr": "Proche d’une limite entre catégories. Privilégiez les proportions mesurées à une étiquette unique.", "de": "Nahe einer Kategoriengrenze. Die gemessenen Proportionen sind aussagekräftiger als eine feste Zuordnung.", "ru": "Результат близок к границе категорий. Ориентируйтесь на измеренные пропорции, а не на один ярлык.", "ar": "النتيجة قريبة من حد فاصل بين الفئات. اعتمد على النسب المقاسة بدلًا من تصنيف ثابت واحد."],
        "vision.closer": ["en": "Move a little closer, keeping the whole face or hand visible.", "zh-Hans": "请稍微靠近，并保持整张脸或整只手可见。", "zh-Hant": "請稍微靠近，並保持整張臉或整隻手可見。", "ja": "全体が見える範囲で、少し近づいてください。", "ko": "얼굴이나 손 전체가 보이도록 조금 더 가까이 오세요.", "vi": "Đưa lại gần một chút, vẫn giữ toàn bộ khuôn mặt hoặc bàn tay trong hình.", "es": "Acércate un poco sin sacar el rostro o la mano del encuadre.", "fr": "Rapprochez-vous un peu en gardant le visage ou la main entièrement visible.", "de": "Etwas näher kommen, ohne Gesicht oder Hand anzuschneiden.", "ru": "Немного приблизьтесь, сохраняя лицо или кисть целиком в кадре.", "ar": "اقترب قليلًا مع إبقاء الوجه أو اليد بالكامل ظاهرًا."],
        "vision.courts": ["en": "The bars compare the upper, middle and lower parts of the tracked face. The upper boundary is the forehead outline, not the hairline.", "zh-Hans": "这些条形图比较追踪到的面部上、中、下三段比例。上界是额头轮廓，并非发际线。", "zh-Hant": "這些條形圖比較追蹤到的面部上、中、下三段比例。上界是額頭輪廓，並非髮際線。", "ja": "バーは検出した顔の上部・中央・下部の割合を示します。上端は額の輪郭で、生え際ではありません。", "ko": "막대는 추적된 얼굴의 위·중간·아래 부분 비율을 비교해요. 위쪽 경계는 이마 윤곽이며 헤어라인이 아니에요.", "vi": "Các thanh so sánh phần trên, giữa và dưới của khuôn mặt được theo dõi. Ranh giới trên là đường viền trán, không phải chân tóc.", "es": "Las barras comparan las partes superior, media e inferior del rostro detectado. El límite superior es el contorno de la frente, no el nacimiento del pelo.", "fr": "Les barres comparent les parties supérieure, centrale et inférieure du visage suivi. La limite haute est le contour du front, pas la ligne des cheveux.", "de": "Die Balken vergleichen oberen, mittleren und unteren Teil des erfassten Gesichts. Die obere Grenze ist die Stirnkontur, nicht der Haaransatz.", "ru": "Полосы сравнивают верхнюю, среднюю и нижнюю части отслеживаемого лица. Верхняя граница — контур лба, а не линия роста волос.", "ar": "تقارن الأشرطة الأجزاء العلوية والوسطى والسفلية من الوجه المتتبَّع. الحد العلوي هو محيط الجبهة، وليس خط الشعر."],
        "vision.faceMethod": ["en": "Proportions use the tracked forehead outline, eyes, nose and chin. The hairline is not detected. These measurements do not establish personality or future events.", "zh-Hans": "根据追踪到的额部轮廓、眼、鼻和下巴估算比例，并未检测发际线。这些测量不能判断性格或未来事件。", "zh-Hant": "根據追蹤到的額部輪廓、眼、鼻和下巴估算比例，並未偵測髮際線。這些測量不能判斷性格或未來事件。", "ja": "額の輪郭・目・鼻・あごから比率を推定します。生え際は検出していません。測定値から性格や将来の出来事は判断できません。", "ko": "추적된 이마 윤곽, 눈, 코, 턱으로 비율을 추정해요. 헤어라인은 감지하지 않아요. 이 측정으로 성격이나 미래를 판단할 수는 없어요.", "vi": "Tỷ lệ dựa trên đường viền trán, mắt, mũi và cằm được theo dõi, không phải đường chân tóc. Các số đo không xác định tính cách hay sự kiện tương lai.", "es": "Las proporciones se estiman con el contorno de la frente, los ojos, la nariz y el mentón. No se detecta el nacimiento del cabello. Estas medidas no determinan la personalidad ni el futuro.", "fr": "Les proportions utilisent le contour du front, les yeux, le nez et le menton. La ligne des cheveux n’est pas détectée. Ces mesures ne permettent pas de déduire la personnalité ou l’avenir.", "de": "Die Proportionen beruhen auf Stirnkontur, Augen, Nase und Kinn. Der Haaransatz wird nicht erkannt. Daraus lassen sich weder Persönlichkeit noch zukünftige Ereignisse ableiten.", "ru": "Пропорции оцениваются по контуру лба, глазам, носу и подбородку. Линия роста волос не определяется. Эти измерения не устанавливают характер или будущие события.", "ar": "تُقدّر النسب من محيط الجبهة والعينين والأنف والذقن. لا يُكتشف خط الشعر. لا تحدد هذه القياسات الشخصية أو الأحداث المستقبلية."],
        "vision.facePose": ["en": "Face the camera with your head level and mouth relaxed.", "zh-Hans": "请正对镜头，头部保持平正，嘴部自然放松。", "zh-Hant": "請正對鏡頭，頭部保持平正，嘴部自然放鬆。", "ja": "顔を正面に向け、頭をまっすぐにし、口元を自然にしてください。", "ko": "카메라를 정면으로 보고 고개를 바르게, 입은 편안하게 유지하세요.", "vi": "Nhìn thẳng vào máy ảnh, giữ đầu ngay ngắn và thả lỏng miệng.", "es": "Mira de frente, con la cabeza recta y la boca relajada.", "fr": "Regardez la caméra, la tête droite et la bouche détendue.", "de": "Gerade in die Kamera schauen, Kopf aufrecht und Mund entspannt halten.", "ru": "Смотрите прямо в камеру, держите голову ровно и расслабьте рот.", "ar": "واجه الكاميرا ورأسك مستقيم وفمك مسترخٍ."],
        "vision.frame": ["en": "Keep the whole face or hand inside the frame.", "zh-Hans": "请让整张脸或整只手都在画面内。", "zh-Hant": "請讓整張臉或整隻手都在畫面內。", "ja": "顔または手の全体を画面に収めてください。", "ko": "얼굴이나 손 전체가 화면 안에 들어오게 하세요.", "vi": "Giữ toàn bộ khuôn mặt hoặc bàn tay trong khung hình.", "es": "Mantén todo el rostro o la mano dentro del encuadre.", "fr": "Gardez tout le visage ou toute la main dans le cadre.", "de": "Das ganze Gesicht oder die ganze Hand im Bild halten.", "ru": "Лицо или кисть должны целиком помещаться в кадре.", "ar": "أبقِ الوجه أو اليد بالكامل داخل الإطار."],
        "vision.hold": ["en": "Hold steady for a moment before measuring.", "zh-Hans": "请保持不动片刻，再开始测量。", "zh-Hant": "請保持不動片刻，再開始測量。", "ja": "少し静止してから測定してください。", "ko": "잠시 움직이지 않은 뒤 측정하세요.", "vi": "Giữ yên một lát trước khi đo.", "es": "Mantén la posición un momento antes de medir.", "fr": "Restez immobile un instant avant de mesurer.", "de": "Vor dem Messen kurz stillhalten.", "ru": "Перед измерением немного побудьте неподвижно.", "ar": "اثبت للحظة قبل القياس."],
        "vision.incomplete": ["en": "Tracking was incomplete. Try again in even light.", "zh-Hans": "追踪不完整，请在均匀光线下重试。", "zh-Hant": "追蹤不完整，請在均勻光線下重試。", "ja": "追跡が不完全です。均一な明るさで再試行してください。", "ko": "추적이 불완전해요. 고른 조명에서 다시 시도하세요.", "vi": "Theo dõi chưa đầy đủ. Hãy thử lại với ánh sáng đều.", "es": "El seguimiento está incompleto. Prueba con luz uniforme.", "fr": "Le suivi est incomplet. Réessayez avec un éclairage uniforme.", "de": "Erfassung unvollständig. Bei gleichmäßiger Beleuchtung erneut versuchen.", "ru": "Отслеживание неполное. Повторите при ровном освещении.", "ar": "التتبع غير مكتمل. حاول مجددًا في إضاءة متساوية."],
        "vision.legacy": ["en": "Saved with the previous measurement method. Read again to use the improved capture.", "zh-Hans": "这是旧测量方法保存的结果。重新读取即可使用改进后的测量。", "zh-Hant": "這是舊測量方法儲存的結果。重新讀取即可使用改進後的測量。", "ja": "以前の測定方法で保存した結果です。再測定すると新しい方法を使えます。", "ko": "이전 측정 방식으로 저장된 결과예요. 다시 읽으면 개선된 방식을 사용해요.", "vi": "Kết quả được lưu bằng cách đo cũ. Đọc lại để dùng cách đo đã cải tiến.", "es": "Guardado con el método anterior. Vuelve a medir para usar la captura mejorada.", "fr": "Résultat enregistré avec l’ancienne méthode. Relancez la lecture pour utiliser la capture améliorée.", "de": "Mit der bisherigen Methode gespeichert. Für die verbesserte Erfassung erneut messen.", "ru": "Сохранено прежним методом. Повторите измерение, чтобы применить улучшенный захват.", "ar": "حُفظت النتيجة بطريقة القياس السابقة. أعد القراءة لاستخدام الالتقاط المحسّن."],
        "vision.measured": ["en": "Combined from 8 steady frames.", "zh-Hans": "由 8 帧稳定画面综合测量。", "zh-Hant": "由 8 幀穩定畫面綜合測量。", "ja": "安定した8フレームを統合した測定です。", "ko": "안정된 8개 프레임을 종합한 측정값이에요.", "vi": "Tổng hợp từ 8 khung hình ổn định.", "es": "Resultado combinado de 8 fotogramas estables.", "fr": "Mesure combinant 8 images stables.", "de": "Aus 8 stabilen Bildern zusammengeführt.", "ru": "Объединены измерения из 8 стабильных кадров.", "ar": "تم دمج القياسات من 8 إطارات ثابتة."],
        "vision.measurement": ["en": "Measurement", "zh-Hans": "测量结果", "zh-Hant": "測量結果", "ja": "測定結果", "ko": "측정 결과", "vi": "Kết quả đo", "es": "Medición", "fr": "Mesure", "de": "Messung", "ru": "Измерение", "ar": "القياس"],
        "vision.mixed": ["en": "Between types", "zh-Hans": "介于类型之间", "zh-Hant": "介於類型之間", "ja": "複数の型の中間", "ko": "유형 사이", "vi": "Giữa các loại", "es": "Entre tipos", "fr": "Entre plusieurs types", "de": "Zwischen Formen", "ru": "Между типами", "ar": "بين الأنواع"],
        "vision.palmMethod": ["en": "Proportions use the outline and joints of an open hand. Lines come from your answers; mount fullness is not measured. Finger spread and thumb angle change with pose.", "zh-Hans": "根据张开手掌的轮廓和关节估算比例。掌纹来自你的回答，未测量掌丘丰满度。手指间距和拇指角度会随姿势改变。", "zh-Hant": "根據張開手掌的輪廓和關節估算比例。掌紋來自你的回答，未測量掌丘豐滿度。手指間距和拇指角度會隨姿勢改變。", "ja": "開いた手の輪郭と関節から比率を推定します。掌線はあなたの回答に基づき、手のひらの膨らみは測定しません。指の開きや親指の角度は姿勢で変わります。", "ko": "편 손의 윤곽과 관절로 비율을 추정해요. 손금은 직접 선택한 답변이며 손바닥의 융기는 측정하지 않아요. 손가락 간격과 엄지 각도는 자세에 따라 달라져요.", "vi": "Tỷ lệ dựa trên đường viền và khớp của bàn tay mở. Đường chỉ tay theo câu trả lời của bạn; độ đầy các gò không được đo. Độ xòe ngón và góc ngón cái thay đổi theo tư thế.", "es": "Las proporciones usan el contorno y las articulaciones de la mano abierta. Las líneas proceden de tus respuestas; no se mide el relieve de los montes. La separación de los dedos y el ángulo del pulgar dependen de la postura.", "fr": "Les proportions utilisent le contour et les articulations de la main ouverte. Les lignes proviennent de vos réponses ; le relief des monts n’est pas mesuré. L’écartement des doigts et l’angle du pouce varient avec la posture.", "de": "Die Proportionen beruhen auf Umriss und Gelenken der offenen Hand. Handlinien stammen aus deinen Angaben; die Wölbung der Handballen wird nicht gemessen. Fingerspreizung und Daumenwinkel ändern sich mit der Haltung.", "ru": "Пропорции оцениваются по контуру и суставам раскрытой кисти. Линии берутся из ваших ответов; выпуклость бугров не измеряется. Разведение пальцев и угол большого пальца зависят от позы.", "ar": "تُقدّر النسب من محيط اليد المفتوحة ومفاصلها. خطوط الكف من إجاباتك، ولا يُقاس بروز مناطق الكف. يتغير تباعد الأصابع وزاوية الإبهام مع الوضعية."],
        "vision.palmPose": ["en": "Face an open, flat palm toward the camera and straighten your fingers.", "zh-Hans": "请将张开的手掌平对镜头，手指自然伸直。", "zh-Hant": "請將張開的手掌平對鏡頭，手指自然伸直。", "ja": "手のひらを平らにしてカメラに向け、指を伸ばしてください。", "ko": "편 손바닥을 카메라와 평행하게 하고 손가락을 펴세요.", "vi": "Hướng lòng bàn tay mở phẳng về máy ảnh và duỗi các ngón tay.", "es": "Muestra la palma abierta de frente y estira los dedos.", "fr": "Présentez la paume ouverte bien à plat face à la caméra, les doigts tendus.", "de": "Die offene Handfläche flach zur Kamera halten und die Finger strecken.", "ru": "Поверните раскрытую ладонь прямо к камере и выпрямите пальцы.", "ar": "وجّه راحة اليد المفتوحة والمسطحة نحو الكاميرا وافرد الأصابع."],
        "vision.ready": ["en": "Ready to measure", "zh-Hans": "可以开始测量", "zh-Hant": "可以開始測量", "ja": "測定できます", "ko": "측정할 수 있어요", "vi": "Sẵn sàng đo", "es": "Listo para medir", "fr": "Prêt à mesurer", "de": "Bereit zum Messen", "ru": "Можно измерять", "ar": "جاهز للقياس"],
        "vision.steady": ["en": "The measurements changed during capture. Hold still and try again.", "zh-Hans": "拍摄期间测量变化较大，请保持不动后重试。", "zh-Hant": "拍攝期間測量變化較大，請保持不動後重試。", "ja": "撮影中に測定値が変動しました。静止して再試行してください。", "ko": "촬영 중 측정값이 변했어요. 움직이지 말고 다시 시도하세요.", "vi": "Số đo thay đổi khi chụp. Hãy giữ yên và thử lại.", "es": "Las medidas cambiaron durante la captura. Mantente quieto e inténtalo otra vez.", "fr": "Les mesures ont changé pendant la capture. Restez immobile et réessayez.", "de": "Die Messwerte haben sich während der Aufnahme verändert. Stillhalten und erneut versuchen.", "ru": "Во время съёмки размеры менялись. Не двигайтесь и повторите.", "ar": "تغيّرت القياسات أثناء الالتقاط. اثبت وحاول مجددًا."],
        "vision.uncertain": ["en": "Near boundary", "zh-Hans": "接近边界", "zh-Hant": "接近邊界", "ja": "境界付近", "ko": "경계에 가까움", "vi": "Gần ranh giới", "es": "Cerca del límite", "fr": "Proche de la limite", "de": "Nahe der Grenze", "ru": "Близко к границе", "ar": "قريب من الحد"],
    ]

